const chatId = $json.chat_id;
const firstName = $json.first_name;

const text = `Hola ${firstName} 👋 ¿Sigues por ahí? Sin apuro si estás con cosas de trabajo, me avisas cuando te acomode y retomamos lo de tu marca.`;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://twenty-bridge:3000/telegram/send',
    body: { chat_id: chatId, action: 'typing' },
    json: true
  });
} catch (e) {}

await new Promise(r => setTimeout(r, 3000));

const resData = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://twenty-bridge:3000/telegram/send',
  body: { chat_id: chatId, text: text, parse_mode: 'HTML' },
  json: true
});

return [{
  json: {
    chat_id: chatId,
    sent: resData?.ok,
    message_id: resData?.result?.message_id
  }
}];

const raw = $json.value;
if (!raw) return [];

try {
  const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const now = Date.now();
  const diffMinutes = (now - (data.timestamp || 0)) / (1000 * 60);

  // Silencio entre 20 y 90 minutos, no reenganchado aún y no finalizado
  if (diffMinutes >= 20 && diffMinutes <= 90 && !data.reengaged && !data.completed) {
    return [{
      json: {
        key: $('Redis: Leer Actividad').first().json.key || `lead:activity:${data.chat_id}`,
        chat_id: data.chat_id,
        first_name: data.first_name || 'hola',
        diff_minutes: Math.round(diffMinutes)
      }
    }];
  }
} catch (e) {}

return [];

const botToken = ($env.TELEGRAM_BOT_TOKEN || process.env.TELEGRAM_BOT_TOKEN);
const chatId = $json.chat_id;
const firstName = $json.first_name;

const text = `Hola ${firstName} 👋 ¿Sigues por ahí? Sin apuro si estás con cosas de trabajo, me avisas cuando te acomode y retomamos lo de tu marca.`;

// 1. Mostrar 'escribiendo...'
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${botToken}/sendChatAction`,
    body: { chat_id: chatId, action: 'typing' },
    json: true
  });
} catch (e) {}

await new Promise(r => setTimeout(r, 3000));

// 2. Enviar mensaje de reenganche
const resData = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${botToken}/sendMessage`,
  body: { chat_id: chatId, text: text, parse_mode: 'HTML' },
  json: true
});

return [{
  json: {
    chat_id: chatId,
    sent: resData.ok,
    message_id: resData.result?.message_id
  }
}];
